CREATE TABLE cliente (nome VARCHAR(20), cidade VARCHAR(20));
CREATE TABLE fornecedor (nome VARCHAR(20), cidade VARCHAR(20));
INSERT INTO cliente VALUES ('Ana', 'Natal'), ('Bia', 'Recife');
INSERT INTO cliente VALUES ('Caio', 'Natal'), ('Davi', 'Manaus');
INSERT INTO fornecedor VALUES ('Alfa', 'Recife'), ('Beta', 'Belem');
INSERT INTO fornecedor VALUES ('Gama', 'Recife');
SELECT COUNT(*) FROM (
  SELECT cidade FROM cliente
  UNION
  SELECT cidade FROM fornecedor
);

