CREATE TABLE func (nome VARCHAR(20), salario INTEGER);
INSERT INTO func VALUES ('Ana', 4500), ('Bia', 2500);
INSERT INTO func VALUES ('Caio', 6000), ('Davi', 3000);
SELECT salario FROM func
EXCEPT
SELECT a.salario
FROM func a JOIN func b ON a.salario < b.salario;

